    "description": "群聊列到对话，私聊时 bot 也知道，反之亦然。 我猜测机制是： 私聊时主上下文就是私聊的对话历史，群聊会作为一部分摘要在上下文，聊到具体细节时再去召回。 但是这个摘要速度怎么赶得上说话速度呢，我再 A 群让 bot1 做了一个事，立马私聊 bot1 ，它会知道刚才做的事，这个是怎么去做到立马组织的记忆呢。 还有一种猜测把所有的群聊和私聊对话按照时间穿成一个上下文里，但是标注对话所在来源。 求大佬们解答",
