    "pub_date": "2026-09-11 17:33:53",
    "author": "",
    "description": "光彩事业是为配合国家八七扶贫攻坚计划，1994年发起，以民营经济人士为参与主体，秉持“义利兼顾、以义为先”理念，依托“光彩事业行”“万企兴万村”等载体，通过产业投资、公益帮扶双轮驱动，在欠发达地区发展产业、促进就业、改善民生，兼具政治性、社会性、公益性的特色社会事业。面对新形势、新任务，推动光彩事业高质量发展需要把握五对关系。",
    "content": "光彩事业是为配合国家八七扶贫攻坚计划，1994年发起，以民营经济人士为参与主体，秉持“义利兼顾、以义为先”理念，依托“光彩事业行”“万企兴万村”等载体，通过产业投资、公益帮扶双轮驱动，在欠发达地区发展产业、促进就业、改善民生，兼具政治性、社会性、公益性的特色社会事业。面对新形势、新任务，推动光彩事业高质量发展需要把握五对关系。"
