    "pub_date": "2026-09-11 17:27:31",
    "author": "",
    "description": "36氪获悉，9月11日，AI安全能力评测基准CyberGym更新榜单。蚂蚁集团AI安全实验室研发的天工Cyber模型与天工Harness以98.5%的漏洞验证成功率位列全球第一。据了解，天工Harness融合了自研天工Cyber模型以及DeepSeek V4 Pro、Qwen 3.8 Max等国产大模型的能力，可完成漏洞分析、PoC构造和结果验证，覆盖复杂软件漏洞验证的端到端流程。",
    "content": "36氪获悉，9月11日，AI安全能力评测基准CyberGym更新榜单。蚂蚁集团AI安全实验室研发的天工Cyber模型与天工Harness以98.5%的漏洞验证成功率位列全球第一。据了解，天工Harness融合了自研天工Cyber模型以及DeepSeek V4 Pro、Qwen 3.8 Max等国产大模型的能力，可完成漏洞分析、PoC构造和结果验证，覆盖复杂软件漏洞验证的端到端流程。"
