    "content": "IT之家 9 月 11 日消息，9 月 11 日上午，市场监管总局召开“破除妨碍统一市场和公平竞争卡点堵点专项行动”专题新闻发布会。 今年 5 月，市场监管总局部署开展破除妨碍统一市场和公平竞争卡点堵点专项行动，紧盯人民群众和经营主体关心关切，立足市场监管职能，依法破除顽固性强、涉及面广、危害性大，企业反映最为强烈的四类卡点堵点问题：一是妨碍企业公平准入自主经营问题；二是限制商品要素自由流动问题；三是资质认定内外有别问题；四是不当实施信用评价设置招标投标区域壁垒问题。 IT之家从发布会获悉，专项行动取得了三方面阶段…"
