    "pub_date": "2026-09-11 17:17:50",
    "author": "澎湃新闻特约撰稿 林民旺",
    "description": "9月10日，中国外交部宣布，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。此次访问的宣布时间距离出访时间不足两日，这种情况在过去并不多见。这个小插曲多少映射出当前中印关系的微妙之处：从宏观层面上看，中印关系保持着平稳且趋于改善的势头，但是如果对中印互动细节进行深入考察，却又令人不得不多几分谨慎。 近年来中印关系趋于回暖的大趋势是清晰可见的。自2024年两国领导人举行喀山会晤后，高层接触逐渐恢复。中印最重…",
    "content": "9月10日，中国外交部宣布，国家主席习近平将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。此次访问的宣布时间距离出访时间不足两日，这种情况在过去并不多见。这个小插曲多少映射出当前中印关系的微妙之处：从宏观层面上看，中印关系保持着平稳且趋于改善的势头，但是如果对中印互动细节进行深入考察，却又令人不得不多几分谨慎。 近年来中印关系趋于回暖的大趋势是清晰可见的。自2024年两国领导人举行喀山会晤后，高层接触逐渐恢复。中印最重要的战略沟通机制首先恢复。2024年12月，中印边界问题特别代表第23次会晤召开…"
