    "content": "新华社阿尔及尔／迪拜9月11日电 热点问答｜阿尔及利亚缘何与阿联酋断交 新华社记者周昊瑾 夏晓 阿尔及利亚外交部10日表示，阿尔及利亚决定即日起与阿联酋断绝外交关系。阿尔及利亚方面此前已“穷尽一切维护双边关系的努力”，并于当天正式告知阿联酋驻阿尔及利亚大使这一决定，要求其在48小时内遵守该决定。那么，两国就断交一事分别作何表态？两国存在哪些深层矛盾？断交将产生什么影响？ 作何表态 阿尔及利亚外交部发表声明说，阿联酋对阿尔及利亚存在一系列挑衅或敌对行为。尽管阿尔及利亚政府屡次警告，阿联酋仍一意孤行，“其行为逾越了主权…"
