    "content": "最近在做行情数据相关的东西，发现一个挺容易搞混的地方： Tick 数据和 K 线数据到底有什么区别？ 一开始我的理解也比较简单，觉得 K 线无非就是把很多条 Tick 数据按照 1 分钟、5 分钟之类的时间周期聚合一下。 后来自己实际处理数据之后，发现两者虽然有关系，但用途其实完全不一样。 如果只是看盘，K 线已经够用了。但如果要做量化策略、盘口分析或者研究某一段时间内价格到底是怎么走出来的，Tick 数据的重要性就会明显很多。 我先用一个比较直观的方式理解 比如某只股票在 10:00 到 10:01 之间发生了很…"
