    "description": "“72岁”的上海静安公园历经九个月闭园改造，将在9月12日以新面貌同市民见面。开园前一天，记者提前探访，可以看到悬铃木大道进行了优化，健身游乐区域得到翻新拓宽。此外，公园围墙也将全部打开。",
    "content": "“72岁”的上海静安公园历经九个月闭园改造，将在9月12日以新面貌同市民见面。开园前一天，记者提前探访，可以看到悬铃木大道进行了优化，健身游乐区域得到翻新拓宽。此外，公园围墙也将全部打开。"
