    "author": "杨旨平",
    "description": "他的对于我的热心的希望，不倦的教诲:小而言之，是为了中国，希望中国有新的医学；大而言之，是为学术，希望新的医学传到中国去。他的性格，在我的眼里和心里是伟大的，虽然他的姓名并不为许多人知道。 只有他的照相，至今还挂在我北京寓居的东墙上。书桌对面，每当夜间疲倦，正想偷懒时，仰面在灯光中瞥见他黑瘦的面貌，似乎正要说出抑扬顿挫的话来，便使我忽又良心发现，而且增加勇气了。于是点上一支烟，再继续写些为正人君子之流所深恶痛疾的文字。",
