    "description": "玉龙喀什河发源于昆仑山，因盛产和田玉，被当地人称为“白玉河”。每年夏季，昆仑山积雪融化，冰川裂解崩落引发的洪水将玉砾和冰块一同冲入河中。经过河流千万年的冲刷磨砺，玉砾逐渐形成了白玉仔料，其中少数演变为珍贵的羊脂玉。 新华社音视频部制作",
