    "content": "新华社华沙9月11日电 综述｜中国技术与投资为中东欧经济转型注入新动能 新华社记者王奕涵 郭爽 为期3天的第35届“经济论坛”10日在波兰西南部城市卡尔帕奇落下帷幕。本届论坛设置500多场活动，议题涵盖经济、人工智能、可持续发展等领域。与会人士认为，随着中东欧国家加快寻找新的经济增长动力，中国在科技创新、产业发展和投资等领域的优势，为双方进一步拓展合作提供了更多机遇。 长期以来，凭借劳动力成本优势以及深度融入欧洲制造业供应链，中东欧地区成为欧洲汽车、机械、电子等产业的重要生产基地。论坛期间发布的一份报告显示，200…"
