    "content": "新华社北京9月11日电 阿拉伯联合酋长国与德国10日宣布，阿联酋计划向德国投资400亿欧元，以深化两国在数字基础设施等领域的合作。 这一消息在阿联酋总统穆罕默德10日开启对德国的首次国事访问时宣布。阿联酋工业部长贾比尔说，德国一直是阿联酋重要的战略和经济伙伴，这项投资计划将助力能够影响未来和提升竞争力的产业领域、技术和岗位。 德国政府说，这笔投资将部分用于建设数字基础设施，包括总容量达1吉瓦的数据中心。双方计划成立一个投资委员会，进一步加强两国间投资与对话，并扩大在人工智能和新技术等领域的合作。 此外，阿联酋与德国…"
